/**
 * Build Geovanta's offline browser and Tauri assets.
 * Without npm dependencies, stage the prebuilt assets shipped with the project.
 */
const fs = require('node:fs');
const path = require('node:path');

const root = path.join(__dirname, '..');
const distAssets = path.join(root, 'dist', 'assets');
const webDir = path.join(root, 'web');
const assetNames = ['geovanta.bundle.js', 'canvaskit.js', 'canvaskit.wasm', 'canvaskit-runtime.js', 'canvaskit-LICENSE.txt',
  'text-font-runtime.js', 'Geovanta-Sans-LICENSE.txt', 'IBM-Plex-LICENSE.txt'];

function findEsbuild() {
  try {
    return require('esbuild');
  } catch (error) {
    if (error.code !== 'MODULE_NOT_FOUND') throw error;
    return null;
  }
}

function buildCanvasKit() {
  const entry = require.resolve('canvaskit-wasm/bin/canvaskit.js');
  const wasmPath = require.resolve('canvaskit-wasm/bin/canvaskit.wasm');
  const wasm = fs.readFileSync(wasmPath);
  const entrySource = fs.readFileSync(entry, 'utf8');
  fs.writeFileSync(path.join(distAssets, 'canvaskit.js'), entrySource);
  fs.copyFileSync(wasmPath, path.join(distAssets, 'canvaskit.wasm'));
  // Supply bytes to CanvasKitInit without a fetch, including on the file:// origin.
  const loader = `
globalThis.initGeovantaCanvasKit = function () {
  const encoded = '${wasm.toString('base64')}';
  if (Uint8Array.fromBase64) return CanvasKitInit({wasmBinary: Uint8Array.fromBase64(encoded)});
  const decoded = atob(encoded);
  const wasmBinary = new Uint8Array(decoded.length);
  for (let i = 0; i < decoded.length; i++) wasmBinary[i] = decoded.charCodeAt(i);
  return CanvasKitInit({wasmBinary});
};
`;
  fs.writeFileSync(path.join(distAssets, 'canvaskit-runtime.js'), entrySource + '\n' + loader);
  fs.copyFileSync(path.join(path.dirname(entry), '..', 'LICENSE'), path.join(distAssets, 'canvaskit-LICENSE.txt'));
}

function buildTextFonts() {
  const folder = path.join(root, 'src', 'assets', 'fonts', 'geovanta-sans');
  const legacyFolder = path.join(root, 'src', 'assets', 'fonts');
  const styles = {
    regular: { file: 'Regular', weight: '400', style: 'normal' },
    bold: { file: 'Bold', weight: '700', style: 'normal' },
    italic: { file: 'Italic', weight: '400', style: 'italic' },
    boldItalic: { file: 'BoldItalic', weight: '700', style: 'italic' }
  };
  const payload = Object.fromEntries(Object.entries(styles).map(([key, meta]) =>
    [key, fs.readFileSync(path.join(folder, `GeovantaSans-${meta.file}.ttf`)).toString('base64')]));
  const woff2Css = Object.values(styles).map(meta => {
    const b64 = fs.readFileSync(path.join(folder, `GeovantaSans-${meta.file}.woff2`)).toString('base64');
    return `@font-face{font-family:'Geovanta Sans';src:url(data:font/woff2;base64,${b64}) format('woff2');font-weight:${meta.weight};font-style:${meta.style};font-display:swap;}`;
  }).join('\n');

  const uiModule = `// Auto-generated by scripts/build-offline-bundle.js — Geovanta Sans 100% offline UI @font-face
export const GEOVANTA_SANS_UI_CSS = ${JSON.stringify(woff2Css)};

export function injectGeovantaSansUiFont(): void {
  if (typeof document === 'undefined' || !document.head) return;
  if (document.getElementById('geovanta-sans-ui-fonts')) return;
  const style = document.createElement('style');
  style.id = 'geovanta-sans-ui-fonts';
  style.textContent = GEOVANTA_SANS_UI_CSS;
  document.head.appendChild(style);
}
`;
  fs.writeFileSync(path.join(legacyFolder, 'geovantaSansUiFontCss.ts'), uiModule);

  const runtime = `
globalThis.GEOVANTA_BUNDLED_TEXT_FONT = {
  family: 'Geovanta Sans',
  faces: Object.fromEntries(Object.entries(${JSON.stringify(payload)}).map(([key, value]) => {
    if (Uint8Array.fromBase64) return [key, Uint8Array.fromBase64(value)];
    const binary = atob(value);
    return [key, Uint8Array.from(binary, ch => ch.charCodeAt(0))];
  }))
};
`;
  fs.writeFileSync(path.join(distAssets, 'text-font-runtime.js'), runtime);
  fs.copyFileSync(path.join(folder, 'Geovanta-Sans-LICENSE.txt'), path.join(distAssets, 'Geovanta-Sans-LICENSE.txt'));
  if (fs.existsSync(path.join(legacyFolder, 'IBM-Plex-LICENSE.txt'))) {
    fs.copyFileSync(path.join(legacyFolder, 'IBM-Plex-LICENSE.txt'), path.join(distAssets, 'IBM-Plex-LICENSE.txt'));
  }
}

async function build() {
  const stagePrebuilt = process.argv.includes('--stage-prebuilt');
  const esbuild = stagePrebuilt ? null : findEsbuild();
  if (!esbuild && !stagePrebuilt) {
    throw new Error('esbuild tidak tersedia. Jalankan npm ci sebelum build:web, atau gunakan --stage-prebuilt untuk menyalin aset lama secara eksplisit.');
  }
  if (esbuild) {
    fs.mkdirSync(distAssets, {recursive: true});
    buildCanvasKit();
    buildTextFonts();
    const fontRuntimeVer = require('node:crypto')
      .createHash('md5')
      .update(fs.readFileSync(path.join(distAssets, 'text-font-runtime.js')))
      .digest('hex')
      .slice(0, 8);
    await esbuild.build({
      entryPoints: [path.join(root, 'src', 'main.tsx')],
      outfile: path.join(distAssets, 'geovanta.bundle.js'),
      bundle: true,
      minify: true,
      format: 'iife',
      jsx: 'transform',
      define: {
        'process.env.NODE_ENV': '"production"',
        '__GEOVANTA_FONT_RUNTIME_VER__': JSON.stringify(fontRuntimeVer)
      }
    });
    const engineEntry = path.join(root, 'scripts', 'mcp-server', 'engineBundleEntry.ts');
    if (fs.existsSync(engineEntry)) {
      await esbuild.build({
        entryPoints: [engineEntry],
        outfile: path.join(root, 'scripts', 'mcp-server', 'engineBundle.cjs'),
        bundle: true,
        platform: 'node',
        format: 'cjs',
        loader: {'.tsx': 'tsx', '.ts': 'ts', '.js': 'js'}
      });
    }
  }

  for (const name of assetNames) {
    if (!fs.existsSync(path.join(distAssets, name))) throw new Error('Aset tidak ditemukan: ' + name + '. Jalankan npm ci.');
  }
  const webAssets = path.join(webDir, 'assets');
  fs.mkdirSync(webAssets, {recursive: true});
  for (const name of assetNames) fs.copyFileSync(path.join(distAssets, name), path.join(webAssets, name));
  const androidAssets = path.join(root, 'android', 'app', 'src', 'main', 'assets', 'public', 'assets');
  if (fs.existsSync(androidAssets)) {
    for (const name of assetNames) fs.copyFileSync(path.join(distAssets, name), path.join(androidAssets, name));
  }
  /* Cache-busting (2026-11-16): bundle di web/index.html memakai ?v=<md5>
     supaya browser tidak menyajikan bundle lama sesudah rebuild. */
  const bundleVer = require('node:crypto').createHash('md5').update(fs.readFileSync(path.join(distAssets, 'geovanta.bundle.js'))).digest('hex').slice(0, 8);
  const htmlSrcPath = fs.existsSync(path.join(root, 'index.html'))
    ? path.join(root, 'index.html')
    : path.join(webDir, 'index.html');
  const html = fs.readFileSync(htmlSrcPath, 'utf8')
    .replaceAll('./dist/assets/', './assets/')
    .replace(/\.\/assets\/geovanta\.bundle\.js(?:\?v=[0-9a-f]+)*/g, './assets/geovanta.bundle.js?v=' + bundleVer);
  fs.writeFileSync(path.join(webDir, 'index.html'), html);
  if (!fs.existsSync(path.join(root, 'index.html'))) {
    fs.writeFileSync(path.join(root, 'index.html'), html);
  }
  console.log('[Geovanta Build] Aset offline CanvasKit GPU/CPU siap di dist/ dan web/.');
}

build().catch(error => {
  console.error('[Geovanta Build] GAGAL:', error);
  process.exitCode = 1;
});
